mapper.select:
select c.cust_id, c.cust_cd, c.cust_nm
  from mst_cust c join srm_supplier s on s.cust_id = c.cust_id
 where c.cust_cd = #{custCd}

mapper.sql:
select  
 where r.created_at >= (#{c.from}::date)::timestamp at time zone #{c.zone}
   and r.created_at < (#{c.to}::date + 1)::timestamp at time zone #{c.zone}
and r.status = #{c.status}

   and (r.return_no ilike #{c.keywordLike} escape '\' or r.ncr_no ilike #{c.keywordLike} escape '\'
        or r.lot_no ilike #{c.keywordLike} escape '\' or i.item_cd ilike #{c.keywordLike} escape '\'
        or c.cust_cd ilike #{c.keywordLike} escape '\' or c.cust_nm ilike #{c.keywordLike} escape '\')

mapper.update:
update srm_return
   set plant_cd = #{v.plantCd}, qty = #{v.qty}, replace_yn = #{v.replaceYn}, po_line_id = #{v.poLineId}, remark = #{v.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where return_id = #{returnId} and status = 'DRAFT' and row_ver = #{rowVer}

update srm_return
   set status = 'CONFIRMED', confirmed_at = now(), confirmed_by = #{by}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where return_id = #{returnId} and status = 'DRAFT' and row_ver = #{rowVer}

update srm_return
   set status = 'CANCELLED', cancel_reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where return_id = #{returnId} and status in ('DRAFT', 'CONFIRMED') and row_ver = #{rowVer}
